import os

from time import time
from taf.rfrl.procedures.resources.python.image_recognition.exceptions import SearchTimeExceeded, \
    PillowInstallationFailed, CouldNotMatchTemplate
from taf.rfrl.procedures.resources.python.logger import log_result, log_operation


def match_template(image_path, template_image_path, matching_percent, output_file_name, save_path,
                   custom_search_width=None, custom_search_height=None, timeout=1800):
    """
    Tries to find template image in searched image.
    :param image_path: full path to image
    :type image_path: str
    :param template_image_path: full path to image template
    :type template_image_path: str
    :param matching_percent: Minimum template coverage in percents, e.g. '80'
    :type matching_percent: Union[str, int]
    :param output_file_name: name (without extension) of an output image file with marked detection zone
    :type output_file_name: str
    :param save_path: path where image with marked detection zone should be saved
    :type save_path: str
    :param custom_search_width: custom width of search area, default is None
    :type custom_search_width: int
    :param custom_search_height: custom height of search area, default is None
    :type custom_search_height: int
    :param timeout: time in seconds to match template, default is 1800
    :type timeout: int
    :raises SearchTimeExceeded: when declared timeout for template matching has been exceeded
    :raises CouldNotMatchTemplate: when template is not present in examined image
    """
    from PIL import Image

    search_image = Image.open(image_path)
    template_image = Image.open(template_image_path)
    matching_percent = int(matching_percent)

    search_width = int(custom_search_width) if custom_search_width else search_image.size[0]
    search_height = int(custom_search_height) if custom_search_height else search_image.size[1]

    template_width, template_height = template_image.size[0], template_image.size[1]
    min_pixel_match = int(template_height * template_width * matching_percent / 100)

    search_image_with_detection = search_image
    search_image = search_image.convert(mode="L")
    template_image = template_image.convert(mode="L")

    search_image = search_image.load()
    template_image = template_image.load()
    template_image_pixels_value = _get_sum_of_pixels_value(image=template_image, image_width=template_width,
                                                           image_height=template_height)
    start_time = time()
    first_column_value = 0
    first_row_value = 0
    initial_row_pixel_value = 0

    log_operation("Starting template matching procedure")
    for y_searched in range(0, search_height - template_height + 1):

        if y_searched != 0:
            search_image_pixels_value = initial_row_pixel_value - first_row_value + \
                sum([search_image[x, y_searched + template_height - 1] for x in range(template_width)])

        else:
            search_image_pixels_value = _get_sum_of_pixels_value(image=search_image, image_width=template_width,
                                                                 image_height=template_height, start_y=y_searched)
        initial_row_pixel_value = search_image_pixels_value
        for x_searched in range(0, search_width - template_width + 1):

            if x_searched != 0:
                search_image_pixels_value = search_image_pixels_value - first_column_value + \
                    sum([search_image[x_searched + template_width - 1, y + y_searched] for y in range(template_height)])

            if (template_image_pixels_value - int(template_image_pixels_value * (matching_percent / 100 - 1))
                    >= search_image_pixels_value
                    >= template_image_pixels_value + int(template_image_pixels_value * (matching_percent / 100 - 1))):

                score = _get_matched_pixels_score(search_image=search_image, x_searched=x_searched,
                                                  y_searched=y_searched, template_image=template_image,
                                                  template_width=template_width, template_height=template_height)

                if score >= min_pixel_match:
                    _save_output_image(image=search_image_with_detection, save_path=save_path,
                                       output_file_name=output_file_name,
                                       detection_x1y1=(x_searched, y_searched),
                                       detection_x2y2=(x_searched + template_width, y_searched + template_height))
                    log_result("Match in location: {}, {} with {}% of template coverage"
                               .format(x_searched, y_searched, int(score / (template_height * template_width) * 100)))

                    return

            if time() - start_time > timeout:
                raise SearchTimeExceeded(f"Couldn't match template in declared timeout={timeout}s")

            first_column_value = sum([search_image[x_searched, y + y_searched] for y in range(template_height)])
        first_row_value = sum([search_image[x, y_searched] for x in range(template_width)])
    raise CouldNotMatchTemplate("Looks like template is not present in examined image")


def get_path_to_templates():
    """
    Returns path to predefined image templates.
    :return: path to image templates folder
    :rtype: str
    """
    return f"{os.path.abspath(__file__).rsplit('/', 1)[0]}/templates"


def setup_image_recognition_environment():
    """
    Verifies Pillow library presence and performs installation if it's not detected in current test environment.
    :raises PillowInstallationFailed: when installation of Pillow library fails
    """
    if _is_pillow_installed():
        log_result("Pillow library is already installed")
    else:
        _install_pillow_library()

        if not _is_pillow_installed():
            raise PillowInstallationFailed("Looks like Pillow installation procedure failed")
        log_result("Pillow library installed successfully")


def _is_pillow_installed():
    cmd_check = "pip freeze | grep Pillow==8.4.0"
    check_lib = os.popen(cmd_check)
    return bool(check_lib.read())


def _install_pillow_library():
    log_operation("Installing pillow library...")
    cmd_install_pillow = "pip install pillow==8.4.0"
    os.system(cmd_install_pillow)


def _get_matched_pixels_score(search_image, x_searched, y_searched, template_width, template_height, template_image):
    return sum([search_image[x_searched + x_template, y_searched + y_template] == template_image[x_template, y_template]
                for x_template in range(template_width)
                for y_template in range(template_height)])


def _save_output_image(image, save_path, output_file_name, detection_x1y1=(), detection_x2y2=()):
    from PIL import ImageDraw

    im_temp = ImageDraw.Draw(image)
    im_temp.rectangle((detection_x1y1[0], detection_x1y1[1], detection_x2y2[0], detection_x2y2[1]),
                      width=2, outline="#FF0000")
    image.save(f'{save_path}/{output_file_name}.png')


def _get_sum_of_pixels_value(image, image_width, image_height, start_x=0, start_y=0):
    pixels_sum = 0

    for y in range(start_y, start_y + image_height):
        for x in range(start_x, start_x + image_width):
            pixels_sum += image[x, y]

    return pixels_sum
